-- V6에서 제거된 last_message_at 복구 (directchat 기능에서 실제 사용)SET @col_exists = (    SELECT COUNT(*) FROM information_schema.COLUMNS    WHERE TABLE_SCHEMA = DATABASE()      AND TABLE_NAME   = 'chat_rooms'      AND COLUMN_NAME  = 'last_message_at');SET @sql = IF(@col_exists = 0,    'ALTER TABLE `chat_rooms` ADD COLUMN `last_message_at` DATETIME NULL AFTER `status`',    'SELECT 1');PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;